CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE IF NOT EXISTS users (user_id text PRIMARY KEY, role text NOT NULL, name text NOT NULL, facility_id text, patient_id text, password_hash text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS facilities (facility_id text PRIMARY KEY, name text NOT NULL, type text, district text NOT NULL, taluka text, status text NOT NULL, active_beds integer NOT NULL DEFAULT 0, specialties jsonb NOT NULL DEFAULT '[]');
CREATE TABLE IF NOT EXISTS patients (patient_id text PRIMARY KEY, name text NOT NULL, dob date, age integer, gender text, phone text, address text, village text, taluka text, district text, registered_facility_id text REFERENCES facilities(facility_id), record_version integer NOT NULL DEFAULT 1, updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS triage_records (triage_id text PRIMARY KEY, patient_id text NOT NULL REFERENCES patients(patient_id), health_worker_id text NOT NULL REFERENCES users(user_id), facility_id text REFERENCES facilities(facility_id), priority text NOT NULL CHECK (priority IN ('EMERGENCY', 'HIGH', 'NORMAL')), indicators jsonb NOT NULL DEFAULT '[]', vitals jsonb NOT NULL DEFAULT '{}', sync_status text NOT NULL DEFAULT 'SYNCED', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS appointments (appointment_id text PRIMARY KEY, patient_id text NOT NULL REFERENCES patients(patient_id), doctor_id text NOT NULL REFERENCES users(user_id), facility_id text REFERENCES facilities(facility_id), appointment_date date NOT NULL, appointment_time time NOT NULL, status text NOT NULL DEFAULT 'BOOKED');
CREATE TABLE IF NOT EXISTS referrals (referral_id text PRIMARY KEY, patient_id text NOT NULL REFERENCES patients(patient_id), referring_facility_id text REFERENCES facilities(facility_id), specialty_required text, priority text, status text NOT NULL DEFAULT 'CREATED', clinical_notes text, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS referral_targets (referral_id text REFERENCES referrals(referral_id), facility_id text REFERENCES facilities(facility_id), response_status text NOT NULL DEFAULT 'PENDING', decision_reason text, PRIMARY KEY (referral_id, facility_id));
CREATE TABLE IF NOT EXISTS consultations (consultation_id text PRIMARY KEY, patient_id text NOT NULL REFERENCES patients(patient_id), doctor_id text NOT NULL REFERENCES users(user_id), facility_id text REFERENCES facilities(facility_id), complaint text, observations text, diagnosis text, notes text, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS prescriptions (prescription_id text PRIMARY KEY, patient_id text NOT NULL REFERENCES patients(patient_id), doctor_id text NOT NULL REFERENCES users(user_id), diagnosis text, items jsonb NOT NULL DEFAULT '[]', instructions text, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS diagnostic_orders (order_id text PRIMARY KEY, patient_id text NOT NULL REFERENCES patients(patient_id), doctor_id text NOT NULL REFERENCES users(user_id), test_name text NOT NULL, status text NOT NULL DEFAULT 'ORDERED', result text, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS followups (followup_id text PRIMARY KEY, patient_id text NOT NULL REFERENCES patients(patient_id), doctor_id text, facility_id text REFERENCES facilities(facility_id), followup_date date NOT NULL, reason text, status text NOT NULL DEFAULT 'SCHEDULED', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS medicines (medicine_id text PRIMARY KEY, facility_id text REFERENCES facilities(facility_id), name text NOT NULL, current_stock integer NOT NULL DEFAULT 0, status text NOT NULL DEFAULT 'AVAILABLE', updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS equipment (equipment_id text PRIMARY KEY, facility_id text REFERENCES facilities(facility_id), name text NOT NULL, available_quantity integer NOT NULL DEFAULT 0, status text NOT NULL DEFAULT 'AVAILABLE', updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS beds (facility_id text PRIMARY KEY REFERENCES facilities(facility_id), total_beds integer NOT NULL DEFAULT 0, occupied_beds integer NOT NULL DEFAULT 0, available_beds integer NOT NULL DEFAULT 0, icu_beds integer NOT NULL DEFAULT 0, available_icu_beds integer NOT NULL DEFAULT 0, updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS doctor_availability (doctor_id text REFERENCES users(user_id), facility_id text REFERENCES facilities(facility_id), specialty text, duty_date date, duty_start time, duty_end time, available boolean NOT NULL DEFAULT true, PRIMARY KEY (doctor_id, duty_date));
CREATE TABLE IF NOT EXISTS audit_logs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id text, role text, action text NOT NULL, patient_id text, facility_id text, result text NOT NULL, reason text, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS patients_phone_idx ON patients(phone);
CREATE INDEX IF NOT EXISTS triage_patient_idx ON triage_records(patient_id, created_at DESC);
CREATE INDEX IF NOT EXISTS audit_patient_idx ON audit_logs(patient_id, created_at DESC);
